an","items":["hh-tantric-personality-portrait.025","hh-tantric-personality-portrait.026","hh-tantric-personality-portrait.027","hh-tantric-personality-portrait.028","hh-tantric-personality-portrait.029","hh-tantric-personality-portrait.030","hh-tantric-personality-portrait.031","hh-tantric-personality-portrait.032"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Согласие и автономия","direction":"higher-reported-resource"},{"key":"resources.tantric_personality_portrait.pleasure","method":"mean","items":["hh-tantric-personality-portrait.033","hh-tantric-personality-portrait.034","hh-tantric-personality-portrait.035","hh-tantric-personality-portrait.036","hh-tantric-personality-portrait.037","hh-tantric-personality-portrait.038","hh-tantric-personality-portrait.039","hh-tantric-personality-portrait.040"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Удовольствие без давления","direction":"higher-reported-resource"},{"key":"resources.tantric_personality_portrait.attention","method":"mean","items":["hh-tantric-personality-portrait.041","hh-tantric-personality-portrait.042","hh-tantric-personality-portrait.043","hh-tantric-personality-portrait.044","hh-tantric-personality-portrait.045","hh-tantric-personality-portrait.046","hh-tantric-personality-portrait.047","hh-tantric-personality-portrait.048"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Медитативное внимание","direction":"higher-reported-resource"},{"key":"resources.tantric_personality_portrait.agency","method":"mean","items":["hh-tantric-personality-portrait.049","hh-tantric-personality-portrait.050","hh-tantric-personality-portrait.051","hh-tantric-personality-portrait.052","hh-tantric-personality-portrait.053","hh-tantric-personality-portrait.054","hh-tantric-personality-portrait.055","hh-tantric-personality-portrait.056"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Личная воля и опора","direction":"higher-reported-resource"},{"key":"resources.tantric_personality_portrait.meaning","method":"mean","items":["hh-tantric-personality-portrait.057","hh-tantric-personality-portrait.058","hh-tantric-personality-portrait.059","hh-tantric-personality-portrait.060","hh-tantric-personality-portrait.061","hh-tantric-personality-portrait.062","hh-tantric-personality-portrait.063","hh-tantric-personality-portrait.064"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Ценности и интеграция","direction":"higher-reported-resource"}]},"questions":[{"id":"hh-tantric-personality-portrait.001","text":"Я замечаю, когда плечи расслабляются.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.002","text":"Я замечаю телесную усталость до полного истощения.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.003","text":"Я различаю движения, которые даются легко.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.004","text":"Я замечаю разницу между теплом и напряжением.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.005","text":"Я могу обратить внимание на нейтральное ощущение.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.006","text":"Я замечаю изменения своей осанки.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.007","text":"Я чувствую, когда нужна физическая дистанция.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.008","text":"Я могу описать ощущение тела, не трактуя его причину.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.009","text":"Я могу распознать чувство прежде, чем действовать.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.010","text":"Я допускаю смешанные эмоции.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.011","text":"Я могу попросить паузу во время сложного разговора.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.012","text":"Я могу проявить грусть, не считая её слабостью.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.013","text":"Я замечаю, когда возбуждение становится чрезмерным.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.014","text":"Я могу назвать разочарование без обвинений другого.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.015","text":"Я знаю мягкий способ вернуть устойчивость при волнении.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.016","text":"Я даю себе время после сильной эмоции.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.017","text":"Я могу слушать, сохраняя внимание к себе.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.018","text":"Я могу проявлять тепло без ожидания определённого ответа.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.019","text":"Я могу спросить, какая поддержка человеку подходит.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.020","text":"Я уважаю разные уровни комфорта с прикосновениями.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.021","text":"Я могу наслаждаться компанией без постоянного разговора.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.022","text":"Я могу попросить заверения, не превращая его в обязанность.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.023","text":"Я замечаю взаимность в отношениях.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.024","text":"Я могу ценить человека, принимая наши различия.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.025","text":"Я могу сказать, чем мне комфортно делиться.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.026","text":"Я могу отказаться от ритуала, не оправдывая свой выбор.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.027","text":"Я уточняю согласие перед прикосновением.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.028","text":"Я могу изменить планы, если перестаю чувствовать безопасность.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.029","text":"Я могу завершить неуважительный разговор.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.030","text":"Я допускаю несогласие другого человека.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.031","text":"Я замечаю, когда действую ради избежания неодобрения.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.032","text":"Я ценю осознанный выбор выше давления участвовать.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.033","text":"Я замечаю, что делает обычный опыт приятным.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.034","text":"Я разрешаю себе тонкое удовольствие вместо интенсивности.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.035","text":"Я могу принимать нежность без необходимости усиливать интимность.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.036","text":"Я могу без смущения назвать сенсорное предпочтение.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.037","text":"Я могу заниматься творчеством без тревоги о продуктивности.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.038","text":"Я допускаю изменения желания, не требуя постоянства.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.039","text":"Я различаю момент, когда близость действительно привлекательна.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.040","text":"Я могу ценить отдых как полноценный источник радости.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.041","text":"Я замечаю, когда внимание уходит в сторону.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.042","text":"Я могу вернуть фокус без упрёков к себе.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.043","text":"Я сохраняю любопытство к новому опыту.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.044","text":"Я могу сделать осознанную паузу в обычных делах.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.045","text":"Я могу наблюдать мысль, не считая её приказом.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.046","text":"Я замечаю, когда практика утомляет ум.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.047","text":"Я могу менять длительность медитации под свои потребности.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.048","text":"Я готов сделать паузу, если концентрация становится чрезмерной.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.049","text":"Я могу выбрать небольшой шаг в направлении своих приоритетов.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.050","text":"Я могу признать, что мне нужна помощь.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.051","text":"Я могу начать несовершенно, не дожидаясь полной определённости.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.052","text":"Я замечаю, когда чужие ожидания заслоняют мои желания.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.053","text":"Я могу уважительно выразить предпочтение.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.054","text":"Я могу пересмотреть цель при изменении обстоятельств.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.055","text":"Я могу ценить усилие без требования яркого результата.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.056","text":"Я могу защищать время для восстановления.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.057","text":"Я могу объяснить, почему практика важна лично для меня.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.058","text":"Я могу задавать вопросы традиции, продолжая уважать её.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.059","text":"Я могу переводить осознание в повседневный выбор.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.060","text":"Я допускаю изменение своего понимания духовности.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.061","text":"Я могу участвовать в значимых ритуалах без утверждений о доказанных сверхъестественных эффектах.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.062","text":"Я могу выбирать светский подход, если он подходит больше.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.063","text":"Я могу отделять свои ценности от чужого одобрения.","required":true,"direction":"higher-reported-resource"},{"id":"hh-tantric-personality-portrait.064","text":"Я могу интегрировать опыт без жёсткого ярлыка для себя.","required":true,"direction":"higher-reported-resource"}],"optionalContext":[],"suggestedRepeatDays":30,"contentHash":"sha256:7b65ec48ac0b62bb7e85ccb616ebf0df3ef98b3d042935730c551916a08730c9"}]
$tantric_definitions$::jsonb)
  loop
    if exists (select 1 from app.assessment_versions av where av.id = (d->>'id')::uuid and av.content_hash <> d->>'contentHash') then
      raise exception 'Refusing to overwrite published tantric assessment %', d->>'id';
    end if;
    insert into app.assessment_versions (
      id,definition_key,definition_version,instrument_locale,translation_version,
      definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
      timeframe,source_metadata,content_hash
    ) values (
      (d->>'id')::uuid,d->>'key',d->>'version',d->>'instrumentLocale',d->>'translationVersion',
      d,d->'questions','{"type":"integer","minimum":0,"maximum":4}'::jsonb,
      d->>'scoringKey',d->>'scoringVersion','{"version":"v1"}'::jsonb,
      d->>'timeframe',d->'source',d->>'contentHash'
    ) on conflict (id) do nothing;
  end loop;
end $$;
